<?php
if(PHP_SAPI!=='cli')exit("CLI only\n");require_once __DIR__.'/../config/database.php';$db=(new Database())->getConnection();$cases=$db->query("SELECT DISTINCT experiment_case_id FROM user_activity_logs WHERE source='simulation' AND actual_label='normal'")->fetchAll(PDO::FETCH_COLUMN);$samples=['login_per_min'=>[],'request_per_min'=>[],'order_per_hour'=>[],'failed_login_per_10min'=>[]];
foreach($cases as$case){$q=$db->prepare("SELECT occurred_at,action,request_count FROM user_activity_logs WHERE source='simulation' AND experiment_case_id=? ORDER BY occurred_at");$q->execute([$case]);$logs=$q->fetchAll();$max=array_fill_keys(array_keys($samples),0);foreach($logs as$a){$t=strtotime($a['occurred_at']);$v=['login_per_min'=>0,'request_per_min'=>0,'order_per_hour'=>0,'failed_login_per_10min'=>0];foreach($logs as$x){$xt=strtotime($x['occurred_at']);if($xt>$t)continue;if($xt>$t-60&&in_array($x['action'],['login.success','login.failed'],true))$v['login_per_min']++;if($xt>$t-60&&$x['action']==='request')$v['request_per_min']+=(int)$x['request_count'];if($xt>$t-3600&&$x['action']==='order.created')$v['order_per_hour']++;if($xt>$t-600&&$x['action']==='login.failed')$v['failed_login_per_10min']++;}foreach($v as$k=>$n)$max[$k]=max($max[$k],$n);}foreach($max as$k=>$n)$samples[$k][]=$n;}
function ss(array$v){$n=count($v);$m=$n?array_sum($v)/$n:0;$s=0;foreach($v as$x)$s+=($x-$m)**2;return[$m,$n>1?sqrt($s/($n-1)):0,$n];}$policy=['login_per_min'=>2,'request_per_min'=>50,'order_per_hour'=>5,'failed_login_per_10min'=>5];$out=[];foreach($samples as$k=>$v){[$m,$sd,$n]=ss($v);$db->prepare('UPDATE behavior_baselines SET mean_value=?,sd_value=?,sample_count=?,calculated_at=NOW(),threshold_value=? WHERE feature_code=?')->execute([$m,$sd,$n,$policy[$k],$k]);$out[$k]=['mean'=>round($m,4),'sd'=>round($sd,4),'threshold'=>$policy[$k],'samples'=>$n];}echo json_encode($out,JSON_PRETTY_PRINT)."\n";
